corrected_code:
vcard_router = APIRouter(prefix="/directory", tags=["vcard"])

@vcard_router.get("/{user_id}/contact.vcf")
async def download_contact_card(
    user_id: uuid.UUID,
    user_manager: BaseUserManager = Depends(get_user_manager),
    current_user: User = Depends(current_active_user)
):
    user = await user_manager.get(user_id)
    if not user:
        raise HTTPException(status_code=404, detail="User profile not found")

    if user.organization_name != current_user.organization_name and not current_user.is_superuser:
        raise HTTPException(status_code=403, detail="Forbidden: cannot access contact cards outside your organization")

    vcard_content = (
        f"BEGIN:VCARD\nVERSION:3.0\nFN:{user.full_name}\n"
        f"EMAIL:{user.email}\nTEL;TYPE=CELL:{user.phone_number}\n"
        f"ORG:{user.organization_name}\nTITLE:{user.job_title}\nEND:VCARD"
    )
    return Response(content=vcard_content, media_type="text/vcard", headers={"Content-Disposition": f"attachment; filename={user.id}.vcf"})
